const MAX_CHANNELS:usize=8;
fn rounded_shift(value:i64,shift:u32)->i64{let divisor=1i64<<shift;if value>=0{value/divisor}else{-((-value+divisor-1)/divisor)}}
#[no_mangle]
pub unsafe extern "C" fn depthconv(v:*const i64,n:usize,out:*mut u8,capacity:usize)->i64{if v.is_null()||n<1||n>1+11*MAX_CHANNELS{return -1;}let values=unsafe{std::slice::from_raw_parts(v,n)};let cc=values[0];if !(1..=MAX_CHANNELS as i64).contains(&cc)||n!=1+11*cc as usize{return -1;}let c=cc as usize;if values[1..1+8*c].iter().any(|&x|!(-128..=127).contains(&x)){return -1;}if values[1+8*c..1+9*c].iter().any(|&x|!(-1_000_000..=1_000_000).contains(&x)){return -1;}if values[1+9*c..1+10*c].iter().any(|&x|!(0..=2_147_483_647).contains(&x)){return -1;}if values[1+10*c..].iter().any(|&x|!(-8..=0).contains(&x)){return -1;}if out.is_null()||capacity<c{return -2;}let output=unsafe{std::slice::from_raw_parts_mut(out,c)};for ch in 0..c{let mut acc=0i32;for y in 0..4{acc+=(values[1+4*c+y*c+ch] as i32)*(values[1+y*c+ch] as i32+128);}acc+=values[1+8*c+ch] as i32;let shift=(31-values[1+10*c+ch]) as u32;let round=1i64<<(shift-1);let mut scaled=rounded_shift(i64::from(acc)*values[1+9*c+ch]+round,shift);scaled=scaled.clamp(-128,127);output[ch]=(scaled as i8) as u8;}c as i64}
